import { GoogleGenAI } from "@google/genai";

const getAiClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    console.error("API_KEY is missing");
    throw new Error("API Key missing");
  }
  return new GoogleGenAI({ apiKey });
};

const RUSTY_LAKE_STYLE_SUFFIX = ", rusty lake game style, hand-drawn sketch, mysterious, surreal, sepia tones, thick outlines, paper texture background, vintage illustration, minimalist details.";

// --- Cache & Queue System ---

// In-memory cache to prevent re-generating the same images during the session
const globalImageCache = new Map<string, string>();

// Queue for serializing requests to avoid hitting concurrency limits
type Task<T> = () => Promise<T>;
const requestQueue: Array<{
  task: Task<any>;
  resolve: (value: any) => void;
  reject: (reason?: any) => void;
}> = [];

let isProcessingQueue = false;
// Delay between queue items to respect rate limits
const REQUEST_DELAY_MS = 2000; 

const processQueue = async () => {
  if (isProcessingQueue || requestQueue.length === 0) return;
  isProcessingQueue = true;

  while (requestQueue.length > 0) {
    const item = requestQueue.shift();
    if (!item) break;

    try {
      const result = await item.task();
      item.resolve(result);
    } catch (error) {
      item.reject(error);
    }

    // Wait before processing the next item to respect rate limits
    if (requestQueue.length > 0) {
      await new Promise((resolve) => setTimeout(resolve, REQUEST_DELAY_MS));
    }
  }

  isProcessingQueue = false;
};

const enqueueRequest = <T>(task: Task<T>): Promise<T> => {
  return new Promise((resolve, reject) => {
    requestQueue.push({ task, resolve, reject });
    processQueue();
  });
};

// Retry logic wrapper
const withRetry = async <T>(fn: () => Promise<T>, retries = 5, backoff = 1000): Promise<T> => {
  try {
    return await fn();
  } catch (error: any) {
    console.warn("API Error caught:", error.message || error);

    // Check for retryable errors (Rate limits, Server errors, Unknown RPC errors, or Model glitches)
    const isRetryable = 
      error?.status === 429 || 
      error?.code === 429 || 
      error?.message?.includes('429') || 
      error?.message?.includes('quota') ||
      error?.status === 'RESOURCE_EXHAUSTED' ||
      error?.status === 500 ||
      error?.code === 500 ||
      error?.status === 503 ||
      error?.code === 503 ||
      error?.status === 'UNKNOWN' ||
      error?.status === 'INTERNAL' ||
      // Retry if the model returned text instead of an image (glitch)
      error?.message?.includes('No valid image data');

    if (isRetryable && retries > 0) {
      console.warn(`Transient error hit (${error?.status || error?.code || 'Custom'}). Retrying in ${backoff}ms... (${retries} attempts left)`);
      await new Promise(resolve => setTimeout(resolve, backoff));
      return withRetry(fn, retries - 1, backoff * 2);
    }
    throw error;
  }
};

// --- API Functions ---

export const generateImage = async (prompt: string): Promise<string> => {
  // Explicitly ask for an image and forbid text to reduce chatty responses
  const fullPrompt = `[IMAGE ONLY] Generate an illustration of ${prompt} ${RUSTY_LAKE_STYLE_SUFFIX} Do not output any text or conversation.`;

  if (globalImageCache.has(fullPrompt)) {
    return globalImageCache.get(fullPrompt)!;
  }

  return enqueueRequest(() => withRetry(async () => {
    try {
      const ai = getAiClient();
      const model = 'gemini-2.5-flash-image';

      const response = await ai.models.generateContent({
        model,
        contents: {
          parts: [{ text: fullPrompt }]
        }
      });

      // Robust check for response structure
      const candidate = response.candidates?.[0];
      const parts = candidate?.content?.parts;

      if (parts && parts.length > 0) {
        for (const part of parts) {
          if (part.inlineData && part.inlineData.data) {
            const result = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
            globalImageCache.set(fullPrompt, result);
            return result;
          }
        }
      }

      // If we are here, we received text instead of an image.
      console.warn("Gemini returned text instead of image. Retrying...");
      throw new Error("No valid image data found in response");
    } catch (error) {
      console.error("Error generating image:", error);
      throw error;
    }
  }));
};

export const editImage = async (base64Image: string, editInstruction: string): Promise<string> => {
  return enqueueRequest(() => withRetry(async () => {
    try {
      const ai = getAiClient();
      const model = 'gemini-2.5-flash-image';

      // Strip the prefix if present to get raw base64
      const base64Data = base64Image.replace(/^data:image\/\w+;base64,/, "");

      const fullInstruction = `[IMAGE ONLY] Edit this image: ${editInstruction}. Maintain the Rusty Lake, hand-drawn sketch style. Keep the sepia/vintage atmosphere. Do not output text.`;

      const response = await ai.models.generateContent({
        model,
        contents: {
          parts: [
            {
              text: fullInstruction
            },
            {
              inlineData: {
                mimeType: 'image/png', // Assuming PNG or standard format
                data: base64Data
              }
            }
          ]
        }
      });

      const candidate = response.candidates?.[0];
      const parts = candidate?.content?.parts;

      if (parts && parts.length > 0) {
        for (const part of parts) {
          if (part.inlineData && part.inlineData.data) {
            return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
          }
        }
      }

      console.warn("Gemini returned text instead of edited image. Retrying...");
      throw new Error("No valid image data found in response");
    } catch (error) {
      console.error("Error editing image:", error);
      throw error;
    }
  }));
};

import { get, set, del, clear, keys } from 'idb-keyval';

const PREFIX = 'mm_img_';

// Format the key to ensure uniqueness per prompt
const formatKey = (prompt: string) => `${PREFIX}${btoa(prompt.slice(0, 100))}`; // Simple hashing/encoding

export const saveImageToStorage = async (prompt: string, base64Data: string) => {
  try {
    const key = formatKey(prompt);
    await set(key, base64Data);
    console.log('Image saved to storage:', key);
  } catch (e) {
    console.error('Failed to save image to storage', e);
  }
};

export const getImageFromStorage = async (prompt: string): Promise<string | undefined> => {
  try {
    const key = formatKey(prompt);
    return await get(key);
  } catch (e) {
    console.error('Failed to retrieve image from storage', e);
    return undefined;
  }
};

export const clearImageCache = async () => {
  try {
    // Only clear items with our prefix, or clear all if app is exclusive
    // idb-keyval default store is shared if not configured, but clear() clears the store.
    // For this app, we can just clear the default store.
    await clear();
    console.log('Storage cleared');
  } catch (e) {
    console.error('Failed to clear storage', e);
  }
};

export const getStorageUsage = async (): Promise<string> => {
  try {
    const allKeys = await keys();
    let totalSize = 0;
    for (const key of allKeys) {
        const val = await get(key);
        if (typeof val === 'string') {
            totalSize += val.length * 2; // Approx bytes for string
        }
    }
    return (totalSize / 1024 / 1024).toFixed(2) + ' MB';
  } catch (e) {
    return 'Unknown';
  }
};

