import { GoogleGenAI, HarmCategory, HarmBlockThreshold } from "@google/genai";
import { getImageFromStorage, saveImageToStorage } from './storageService';

const getAiClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    console.error("API_KEY is missing");
    throw new Error("API Key missing");
  }
  return new GoogleGenAI({ apiKey });
};

const RUSTY_LAKE_STYLE_SUFFIX = ", rusty lake game style, hand-drawn sketch, mysterious, surreal, sepia tones, thick outlines, paper texture background, vintage illustration, minimalist details.";

// --- Queue System ---

// Queue for serializing requests
type Task<T> = () => Promise<T>;
const requestQueue: Array<{
  task: Task<any>;
  resolve: (value: any) => void;
  reject: (reason?: any) => void;
}> = [];

let isProcessingQueue = false;
const REQUEST_DELAY_MS = 2000; 

const processQueue = async () => {
  if (isProcessingQueue || requestQueue.length === 0) return;
  isProcessingQueue = true;

  while (requestQueue.length > 0) {
    const item = requestQueue.shift();
    if (!item) break;

    try {
      const result = await item.task();
      item.resolve(result);
    } catch (error) {
      item.reject(error);
    }

    if (requestQueue.length > 0) {
      await new Promise((resolve) => setTimeout(resolve, REQUEST_DELAY_MS));
    }
  }

  isProcessingQueue = false;
};

const enqueueRequest = <T>(task: Task<T>): Promise<T> => {
  return new Promise((resolve, reject) => {
    requestQueue.push({ task, resolve, reject });
    processQueue();
  });
};

// Retry logic wrapper
const withRetry = async <T>(fn: () => Promise<T>, retries = 5, backoff = 1000): Promise<T> => {
  try {
    return await fn();
  } catch (error: any) {
    console.warn("API Error caught:", error.message || error);

    const isRetryable = 
      error?.status === 429 || 
      error?.code === 429 || 
      error?.message?.includes('429') || 
      error?.message?.includes('quota') ||
      error?.status === 'RESOURCE_EXHAUSTED' ||
      error?.status === 500 ||
      error?.code === 500 ||
      error?.status === 503 ||
      error?.code === 503 ||
      error?.status === 'UNKNOWN' ||
      error?.status === 'INTERNAL' ||
      error?.message?.includes('No valid image data');

    if (isRetryable && retries > 0) {
      console.warn(`Transient error hit (${error?.status || error?.code || 'Custom'}). Retrying in ${backoff}ms... (${retries} attempts left)`);
      await new Promise(resolve => setTimeout(resolve, backoff));
      return withRetry(fn, retries - 1, backoff * 2);
    }
    throw error;
  }
};

