export const BookCover: React.FC<BookCoverProps> = ({ book, onOpen, onBack }) => {
  if (!book) return null;

  // Visual config based on book ID
  const isRedBlack = book.id === 'red_black';

  const coverBg = isRedBlack ? '#1a1a1a' : '#2c241b';
  const textColor = isRedBlack ? '#f0f0f0' : '#d4cbb8';
  const accentColor = isRedBlack ? '#cf1313' : '#8a7a5f';
  const spineColor = isRedBlack ? '#000000' : '#1a1510';
  const titleFont = isRedBlack ? 'font-sans font-black tracking-tighter' : 'font-title tracking-widest';
  const icon = isRedBlack ? '⚖️' : '♾️';

  return (
    <div className="min-h-screen flex items-center justify-center p-4 relative" style={{ backgroundColor: isRedBlack ? '#e5e5e5' : 'transparent' }}>

      <button 
        onClick={onBack}
        className={`absolute top-4 left-4 z-50 p-2 rounded-full transition-colors flex items-center gap-2 group
            ${isRedBlack ? 'text-black hover:bg-gray-200' : 'text-[#5c4d3c] hover:bg-[#d6cfc4]'}
