      >
        <ArrowLeft size={20} />
        <span className="font-mono text-xs opacity-0 group-hover:opacity-100 transition-opacity">Library</span>
      </button>

      <motion.div 
        initial={{ scale: 0.9, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        transition={{ duration: 1, type: 'spring' }}
        className="relative w-full max-w-md aspect-[3/4] cursor-pointer group perspective-1000"
        onClick={onOpen}
      >
        {/* Book Spine effect */}
        <div className="absolute left-0 top-0 bottom-0 w-4 rounded-l-sm z-0 transform -translate-x-2" style={{ backgroundColor: spineColor }}></div>

        {/* Cover */}
        <div 
            className="absolute inset-0 rounded-r-md shadow-2xl flex flex-col items-center justify-center border-r-4 border-b-4 transition-transform duration-500 group-hover:-translate-y-2 group-hover:-translate-x-1"
            style={{ 
                backgroundColor: coverBg,
                borderColor: spineColor
            }}
        >
          {/* Decorative Borders */}
          <div className="absolute inset-2 border-2 rounded-sm opacity-50" style={{ borderColor: accentColor }}></div>
          <div className="absolute inset-4 border rounded-sm opacity-30" style={{ borderColor: accentColor }}></div>

          <div className="p-8 text-center space-y-8 z-10 relative">
            <h1 className={`${titleFont} text-4xl md:text-5xl leading-relaxed uppercase`} style={{ color: textColor }}>
              {book.title.split(' ').map((word, i) => (
                  <span key={i} className="block">{word}</span>
              ))}
            </h1>

            <div className="w-16 h-16 mx-auto border-2 rounded-full flex items-center justify-center opacity-80" style={{ borderColor: textColor }}>
               <span className="text-2xl" style={{ color: textColor }}>{icon}</span>
            </div>

            <p className="font-hand text-lg mt-8" style={{ color: accentColor }}>
              {book.author}
