import { GoogleGenAI, HarmCategory, HarmBlockThreshold } from "@google/genai";
import { getImageFromStorage, saveImageToStorage } from './storageService';

const getAiClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    console.error("API_KEY is missing");
    throw new Error("API Key missing");
  }
  return new GoogleGenAI({ apiKey });
};

// --- Style Definitions ---
export const STYLES = {
  RUSTY_LAKE: "art style of Rusty Lake games, surreal, sepia-toned, hand-drawn sketch, vintage, mysterious, thick outlines, paper texture",
  RED_BLACK: "abstract european modernism, flat vector art, lineless, tarot card aesthetic, dominant red and black colors, geometric, bauhaus influence, minimalist, symbolic, high contrast"
};

// --- Prompt Construction ---
const getFullPrompt = (prompt: string, stylePreset: keyof typeof STYLES = 'RUSTY_LAKE') => {
  const styleSuffix = STYLES[stylePreset];
  return `A surreal illustration of ${prompt}. ${styleSuffix}. High contrast, minimal detail.`;
}

// --- Queue System ---

// Queue for serializing requests
type Task<T> = () => Promise<T>;
const requestQueue: Array<{
  task: Task<any>;
  resolve: (value: any) => void;
  reject: (reason?: any) => void;
}> = [];

let isProcessingQueue = false;
// Increased delay to 4000ms to prevent hitting rate limits (429)
const REQUEST_DELAY_MS = 4000; 

const processQueue = async () => {
  if (isProcessingQueue || requestQueue.length === 0) return;
  isProcessingQueue = true;

  while (requestQueue.length > 0) {
    const item = requestQueue.shift();
    if (!item) break;

    try {
      const result = await item.task();
      item.resolve(result);
    } catch (error) {
      item.reject(error);
    }

    if (requestQueue.length > 0) {
      await new Promise((resolve) => setTimeout(resolve, REQUEST_DELAY_MS));
    }
  }

  isProcessingQueue = false;
};

const enqueueRequest = <T>(task: Task<T>): Promise<T> => {
  return new Promise((resolve, reject) => {
    requestQueue.push({ task, resolve, reject });
    processQueue();
  });
};

// Retry logic wrapper
const withRetry = async <T>(fn: () => Promise<T>, retries = 3, backoff = 2000): Promise<T> => {
  try {
    return await fn();
  } catch (error: any) {
    // Inspect error structure deeply to catch nested error objects
    const status = error?.status || error?.response?.status || error?.error?.status;
    const code = error?.code || error?.response?.code || error?.error?.code;
    const message = error?.message || error?.error?.message || JSON.stringify(error);

    console.warn(`API Error caught: ${status || code} - ${message}`);

    const isRetryable = 
      status === 429 || 
      code === 429 || 
      String(message).includes('429') || 
      String(message).includes('quota') ||
      status === 'RESOURCE_EXHAUSTED' ||
      code === 'RESOURCE_EXHAUSTED' ||
      status === 500 ||
      code === 500 ||
      status === 503 ||
      code === 503 ||
      status === 'UNKNOWN' ||
      status === 'INTERNAL' ||
      String(message).includes('No valid image data');

    if (isRetryable && retries > 0) {
      console.warn(`Transient error hit. Retrying in ${backoff}ms... (${retries} attempts left)`);
      await new Promise(resolve => setTimeout(resolve, backoff));
      return withRetry(fn, retries - 1, backoff * 2);
    }
    throw error;
  }
};

// --- API Functions ---

export const generateImage = async (prompt: string, stylePreset: keyof typeof STYLES = 'RUSTY_LAKE'): Promise<string> => {
  const fullPrompt = getFullPrompt(prompt, stylePreset);

  // 1. Check persistent storage first
  const cached = await getImageFromStorage(fullPrompt);
  if (cached) {
    console.log("Serving from cache:", prompt);
    return cached;
  }

  // 2. Queue and Generate
  return enqueueRequest(() => withRetry(async () => {
    try {
      const ai = getAiClient();
      const model = 'gemini-2.5-flash-image';

      const response = await ai.models.generateContent({
        model,
        contents: {
          parts: [{ text: fullPrompt }]
        },
        config: {
          imageConfig: {
             aspectRatio: "1:1"
          },
          safetySettings: [
            { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
            { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
            { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
            { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE },
          ]
        }
      });

      const candidate = response.candidates?.[0];

      if (candidate?.finishReason !== 'STOP') {
        console.warn(`Image generation finished with reason: ${candidate?.finishReason}`);
      }

      const parts = candidate?.content?.parts;

      if (parts && parts.length > 0) {
        for (const part of parts) {
          if (part.inlineData && part.inlineData.data) {
            const result = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
            // 3. Save to storage
            await saveImageToStorage(fullPrompt, result);
            return result;
          }
        }

        // Log text if present (debugging why image wasn't returned)
        const textPart = parts.find(p => p.text);
        if (textPart) {
           console.warn("Model returned text instead of image:", textPart.text);
        }
      }

      console.warn("Gemini returned text or no data. Response parts:", parts);
      throw new Error("No valid image data found in response");
    } catch (error) {
      console.error("Error generating image:", error);
      throw error;
    }
  }));
};

export const editImage = async (base64Image: string, editInstruction: string, stylePreset: keyof typeof STYLES = 'RUSTY_LAKE'): Promise<string> => {
  return enqueueRequest(() => withRetry(async () => {
    try {
      const ai = getAiClient();
      const model = 'gemini-2.5-flash-image';
      const base64Data = base64Image.replace(/^data:image\/\w+;base64,/, "");

      const styleSuffix = STYLES[stylePreset];
      const fullInstruction = `Edit this image: ${editInstruction}. Style: ${styleSuffix}`;

      const response = await ai.models.generateContent({
        model,
        contents: {
          parts: [
            { text: fullInstruction },
            { inlineData: { mimeType: 'image/png', data: base64Data } }
          ]
        },
        config: {
          imageConfig: {
             aspectRatio: "1:1"
          },
          safetySettings: [
            { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
            { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
            { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
            { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE },
          ]
        }
      });

      const candidate = response.candidates?.[0];
      const parts = candidate?.content?.parts;

      if (parts && parts.length > 0) {
        for (const part of parts) {
          if (part.inlineData && part.inlineData.data) {
             const result = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
             // We return edited images directly without overwriting the original cache
             return result;
          }
        }
      }

      console.warn("Gemini returned text instead of edited image. Retrying...");
      throw new Error("No valid image data found in response");
    } catch (error) {
      console.error("Error editing image:", error);
      throw error;
    }
  }));
};

// Allow user to upload their own image and override the cache for a specific prompt
export const saveCustomImage = async (prompt: string, base64Data: string, stylePreset: keyof typeof STYLES = 'RUSTY_LAKE') => {
    const fullPrompt = getFullPrompt(prompt, stylePreset);
    await saveImageToStorage(fullPrompt, base64Data);
};

