// --- Queue System ---

// Queue for serializing requests
type Task<T> = () => Promise<T>;
const requestQueue: Array<{
  task: Task<any>;
  resolve: (value: any) => void;
  reject: (reason?: any) => void;
}> = [];

let isProcessingQueue = false;
// 6000ms = 10 requests per minute max (safe for 15 RPM limit)
const REQUEST_DELAY_MS = 6000; 

const processQueue = async () => {
  if (isProcessingQueue || requestQueue.length === 0) return;
  isProcessingQueue = true;

  while (requestQueue.length > 0) {
    const item = requestQueue.shift();
    if (!item) break;

    try {
      const result = await item.task();
      item.resolve(result);
    } catch (error) {
      item.reject(error);
    }

    if (requestQueue.length > 0) {
      await new Promise((resolve) => setTimeout(resolve, REQUEST_DELAY_MS));
    }
  }

  isProcessingQueue = false;
};

const enqueueRequest = <T>(task: Task<T>): Promise<T> => {
  return new Promise((resolve, reject) => {
    requestQueue.push({ task, resolve, reject });
    processQueue();
  });
};

// Retry logic wrapper
const withRetry = async <T>(fn: () => Promise<T>, retries = 5, backoff = 5000): Promise<T> => {
  try {
    return await fn();
  } catch (error: any) {
    // Attempt to parse error if it's a JSON string in message
    let errObj = error;
    if (typeof error.message === 'string' && error.message.trim().startsWith('{')) {
        try {
            errObj = JSON.parse(error.message);
        } catch (e) {
            // ignore parse error
        }
    }

    // If the error is wrapped in an 'error' property (common in Google APIs), unwrap it
    if (errObj?.error) {
        errObj = errObj.error;
    }

    const status = errObj?.status || errObj?.code || error?.status;
    const message = errObj?.message || error?.message || JSON.stringify(errObj);

    console.warn(`API Error caught: ${status} - ${message}`);

    const isRateLimit = 
      String(status) === '429' || 
      String(status) === 'RESOURCE_EXHAUSTED' ||
      String(message).includes('429') || 
      String(message).includes('quota') ||
      String(message).includes('RESOURCE_EXHAUSTED');

    const isTransient = 
      String(status) === '500' ||
      String(status) === '503' ||
      String(message).includes('No valid image data') ||
      String(message).includes('Overloaded');

    if ((isRateLimit || isTransient) && retries > 0) {
      // Exponential backoff
      const waitTime = isRateLimit ? backoff * 2 : backoff; // Aggressive backoff for rate limits

      console.warn(`Retrying in ${Math.round(waitTime/1000)}s... (${retries} attempts left)`);
      await new Promise(resolve => setTimeout(resolve, waitTime));

      return withRetry(fn, retries - 1, waitTime * 1.5);
    }

    // Throw a clean error
    throw new Error(`Gemini API Error: ${message}`);
  }
};

