import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { JULIEN_NETWORK, JULIEN_LINKS } from '../constants';
import { NetworkNode } from '../types';
import { GenerativeImage } from './GenerativeImage';
import { X, Info } from 'lucide-react';

export const JulienNetwork: React.FC = () => {
  const [selectedNode, setSelectedNode] = useState<NetworkNode | null>(null);

  return (
    <div className="min-h-screen bg-[#f0f0f0] relative overflow-hidden flex items-center justify-center font-sans">

      {/* Title */}
      <div className="absolute top-20 left-4 md:left-8 z-20 pointer-events-none">
        <h2 className="text-4xl font-black uppercase tracking-tighter text-black/80">Social Web</h2>
        <p className="font-mono text-xs text-red-700 tracking-widest mt-1">THE RED AND THE BLACK</p>
      </div>

      {/* Network Container */}
      <div className="relative w-full h-[80vh] md:h-screen max-w-6xl mx-auto">

        {/* SVG Connections Layer */}
        <svg className="absolute inset-0 w-full h-full pointer-events-none z-0">
          {JULIEN_LINKS.map((link, i) => {
            const startNode = JULIEN_NETWORK.find(n => n.id === link.from);
            const endNode = JULIEN_NETWORK.find(n => n.id === link.to);
            if (!startNode || !endNode) return null;

            return (
              <g key={`link-${i}`}>
                 <motion.line 
                    initial={{ pathLength: 0, opacity: 0 }}
                    animate={{ pathLength: 1, opacity: 0.3 }}
                    transition={{ duration: 1, delay: 0.5 }}
                    x1={`${startNode.x}%`} y1={`${startNode.y}%`}
                    x2={`${endNode.x}%`} y2={`${endNode.y}%`}
                    stroke={link.color || 'black'}
                    strokeWidth={link.type === 'solid' ? 2 : 1}
                    strokeDasharray={link.type === 'dashed' ? "5,5" : link.type === 'dotted' ? "2,2" : "none"}
                  />
                  {/* Label in the middle */}
                  {link.label && (
                      <text 
                        x={(startNode.x + endNode.x) / 2 + '%'} 
                        y={(startNode.y + endNode.y) / 2 + '%'}
                        fill={link.color || 'black'}
                        fontSize="10"
                        fontFamily="monospace"
                        textAnchor="middle"
                        alignmentBaseline="middle"
                        className="bg-white/50"
                        opacity="0.6"
                      >
                          {link.label}
                      </text>
                  )}
              </g>
            );
          })}
        </svg>

        {/* Interactive Nodes */}
        {JULIEN_NETWORK.map(node => (
          <div 
            key={node.id}
            className="absolute transform -translate-x-1/2 -translate-y-1/2 cursor-pointer z-10 group"
            style={{ left: `${node.x}%`, top: `${node.y}%` }}
            onClick={() => setSelectedNode(node)}
          >
             <motion.div
                whileHover={{ scale: 1.15 }}
                initial={{ opacity: 0, scale: 0 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ duration: 0.5, delay: 0.2 }}
                className="flex flex-col items-center"
             >
                <div className={`
                    relative rounded-full overflow-hidden shadow-xl transition-all duration-300 bg-white
                    ${node.size === 'lg' ? 'w-28 h-28 md:w-36 md:h-36 border-4' : node.size === 'md' ? 'w-20 h-20 md:w-24 md:h-24 border-2' : 'w-14 h-14 md:w-16 md:h-16 border'}
                    ${node.color === 'red' ? 'border-[#cf1313]' : node.color === 'gold' ? 'border-[#b8860b]' : 'border-black'}
                `}>
                    {/* Only load image if central node or clicked, to save quota. Otherwise showing Initials/Placeholder */}
                    {node.size === 'lg' ? (
                        <GenerativeImage 
                            initialPrompt={node.imagePrompt}
                            alt={node.name}
                            stylePreset="RED_BLACK"
                            className="w-full h-full"
                        />
                    ) : (
                        <div className="w-full h-full flex flex-col items-center justify-center bg-gray-50 text-center p-1 group-hover:hidden">
                             <span className="font-bold text-xs uppercase">{node.name.split(' ')[0]}</span>
                        </div>
                    )}

                    {/* Reveal image on hover for smaller nodes */}
                    {node.size !== 'lg' && (
                        <div className="absolute inset-0 hidden group-hover:block">
                             <GenerativeImage 
                                initialPrompt={node.imagePrompt}
                                alt={node.name}
                                stylePreset="RED_BLACK"
                                className="w-full h-full"
                            />
                        </div>
                    )}
                </div>

                {/* Floating Label */}
                <div className="absolute top-full mt-2 bg-white/90 backdrop-blur px-3 py-1 rounded shadow-sm border border-black/10 text-center whitespace-nowrap z-20">
                    <span className="block font-bold text-xs uppercase tracking-wider text-black">{node.name}</span>
                    <span className={`block text-[9px] font-mono mt-0.5 uppercase ${node.color === 'red' ? 'text-red-600' : 'text-gray-500'}`}>{node.role}</span>
                </div>
             </motion.div>
          </div>
        ))}

      </div>

      {/* Detail Panel */}
      <AnimatePresence>
        {selectedNode && (
            <motion.div
                initial={{ x: '100%', opacity: 0 }}
                animate={{ x: 0, opacity: 1 }}
                exit={{ x: '100%', opacity: 0 }}
                transition={{ type: 'spring', damping: 25 }}
                className="fixed inset-y-0 right-0 w-full md:w-[450px] bg-white shadow-2xl z-50 border-l-4 border-black overflow-y-auto"
            >
                <div className="relative h-full flex flex-col">

                    {/* Close Button */}
                    <button 
                        onClick={() => setSelectedNode(null)} 
                        className="absolute top-4 right-4 z-20 bg-black text-white p-2 rounded-full hover:bg-red-600 transition-colors"
                    >
                        <X size={20} />
                    </button>

                    {/* Image Header */}
                    <div className="w-full aspect-square bg-gray-100 relative">
                         <GenerativeImage 
                            initialPrompt={selectedNode.imagePrompt}
                            alt={selectedNode.name}
                            stylePreset="RED_BLACK"
                            className="w-full h-full"
                        />
                         <div className="absolute inset-0 bg-gradient-to-t from-black/80 to-transparent pointer-events-none"></div>
                         <div className="absolute bottom-6 left-6 text-white">
                             <h2 className="text-4xl font-black uppercase leading-none mb-2">{selectedNode.name}</h2>
                             <span className={`px-2 py-1 text-xs font-bold uppercase tracking-widest bg-white text-black`}>
                                {selectedNode.role}
                             </span>
                         </div>
                    </div>

                    {/* Content */}
                    <div className="p-8 space-y-8 flex-1 bg-white">

                        {/* Traits */}
                        <div className="flex gap-2 flex-wrap">
                            {selectedNode.traits.split(',').map((trait, i) => (
                                <span key={i} className="px-3 py-1 rounded-full border border-black text-xs font-mono font-bold hover:bg-black hover:text-white transition-colors cursor-default">
                                    {trait.trim()}
                                </span>
                            ))}
                        </div>

                        {/* Description */}
                        <div>
                            <h3 className="flex items-center gap-2 font-bold uppercase text-sm mb-3 text-gray-400">
                                <Info size={16} />
                                Analysis
                            </h3>
                            <p className="text-lg leading-relaxed font-medium text-gray-800">
                                {selectedNode.description}
                            </p>
                        </div>

                        {/* Symbolic Color */}
                        <div className="border-t pt-6">
                             <h3 className="font-bold uppercase text-xs mb-2 text-gray-400">Archetype Color</h3>
                             <div className="flex items-center gap-3">
                                 <div className={`w-8 h-8 rounded-full border-2 border-gray-200 shadow-inner
                                    ${selectedNode.color === 'red' ? 'bg-[#cf1313]' : 
                                      selectedNode.color === 'black' ? 'bg-black' : 
                                      selectedNode.color === 'white' ? 'bg-white' : 
                                      selectedNode.color === 'gold' ? 'bg-[#b8860b]' : 'bg-gray-400'}
                                 `}></div>
                                 <span className="font-mono text-sm capitalize">{selectedNode.color}</span>
                             </div>
                        </div>

                    </div>
                </div>
            </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

