                                         node.alignment === 'black' ? '#000000' : 
                                         'transparent', // Mixed handled below
                            // Special handling for mixed border (half-red, half-black)
                            borderImage: node.alignment === 'mixed' ? 'linear-gradient(to right, #cf1313 50%, #000000 50%) 1' : undefined,
                            // Fallback for rounded corners with gradient borders (CSS limitation: border-image kills border-radius)
                            // We use a box-shadow hack or pseudo element for rounded mixed borders if needed, 
                            // but for now simple border-color logic:
                            borderLeftColor: node.alignment === 'mixed' ? '#cf1313' : undefined,
                            borderTopColor: node.alignment === 'mixed' ? '#cf1313' : undefined,
                            borderRightColor: node.alignment === 'mixed' ? '#000000' : undefined,
                            borderBottomColor: node.alignment === 'mixed' ? '#000000' : undefined
