                        `}>
                            {node.role}
                        </span>
                    </div>
                 </div>
              </motion.div>
            );
        })}
        </AnimatePresence>

      </div>

      {/* Detail Panel */}
      <AnimatePresence>
        {selectedNode && (
            <motion.div
                initial={{ x: '100%', opacity: 0 }}
                animate={{ x: 0, opacity: 1 }}
                exit={{ x: '100%', opacity: 0 }}
