import React, { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { LOTR_CHARACTERS } from '../constants';
import { Character } from '../types';
import { GenerativeImage } from './GenerativeImage';
import { X, Sword, Shield, Map, Info, Star, Bookmark, Share2 } from 'lucide-react';

// Character Tree Positioning (Conceptual Tree of Life)
const TREE_POSITIONS: Record<string, { x: number, y: number }> = {
  // Maiar / Wizards (Top Crown)
  'gandalf': { x: 50, y: 12 },
  'saruman': { x: 35, y: 15 },

  // Elves (Left Branch)
  'galadriel': { x: 20, y: 35 },
  'celeborn': { x: 10, y: 35 },
  'elrond': { x: 25, y: 50 },
  'arwen': { x: 25, y: 65 },
  'thranduil': { x: 10, y: 50 },
  'legolas': { x: 10, y: 65 },

  // Men (Right Branch)
  'aragorn': { x: 45, y: 65 },
  'boromir': { x: 65, y: 50 },
  'faramir': { x: 65, y: 65 },
  'eowyn': { x: 75, y: 65 },
  'theoden': { x: 70, y: 45 },

  // Hobbits (Base / Roots)
  'bilbo': { x: 40, y: 88 },
  'frodo': { x: 50, y: 85 },
  'samwise': { x: 60, y: 88 },

  // Darkness (Shadow)
  'sauron': { x: 85, y: 20 },
  'witchking': { x: 80, y: 35 },
  'gollum': { x: 85, y: 50 }
};

export const LotRCharacters: React.FC = () => {
  const [selectedChar, setSelectedChar] = useState<Character | null>(null);

  const links = useMemo(() => {
    const l: Array<{ from: string, to: string, type: 'blood' | 'faction' }> = [];
    LOTR_CHARACTERS.forEach(char => {
        if (char.parents) char.parents.forEach(p => l.push({ from: p, to: char.id, type: 'blood' }));
        if (char.partner) l.push({ from: char.partner, to: char.id, type: 'blood' });
    });
    return l;
  }, []);

  return (
    <div className="min-h-screen bg-[#f4f1ea] p-4 font-serif paper-texture relative overflow-hidden">

      {/* Background Title Decor */}
      <div className="absolute inset-0 pointer-events-none opacity-[0.05] select-none flex items-center justify-center overflow-hidden">
          <h1 className="text-[25rem] font-black uppercase tracking-tighter leading-none font-title rotate-[-5deg]">The Tree of Fate</h1>
      </div>

      <div className="max-w-7xl mx-auto h-[90vh] relative z-10">
        <header className="text-center mb-4 pt-8">
          <div className="inline-block px-8 py-1 border-y border-[#1a120b]/20 text-[#8a7a5f] font-mono text-[9px] tracking-[0.6em] uppercase mb-2 font-bold">The Archives of Westmarch</div>
          <h2 className="text-3xl md:text-5xl font-black text-[#1a120b] tracking-tighter uppercase leading-none font-title">The Tree of Life</h2>
        </header>

        {/* Tree Container */}
        <div className="relative w-full h-full bg-white/30 rounded-full border border-black/5 shadow-inner backdrop-blur-[1px]">

          {/* SVG Connection Layer */}
          <svg className="absolute inset-0 w-full h-full pointer-events-none opacity-40">
            <defs>
               <filter id="glow">
                  <feGaussianBlur stdDeviation="1" result="coloredBlur"/>
                  <feMerge>
                     <feMergeNode in="coloredBlur"/><feMergeNode in="SourceGraphic"/>
                  </feMerge>
               </filter>
            </defs>
            {links.map((link, i) => {
              const start = TREE_POSITIONS[link.from];
              const end = TREE_POSITIONS[link.to];
              if (!start || !end) return null;
              return (
                <motion.line 
                  key={`link-${i}`}
                  initial={{ pathLength: 0 }}
                  animate={{ pathLength: 1 }}
                  x1={`${start.x}%`} y1={`${start.y}%`}
                  x2={`${end.x}%`} y2={`${end.y}%`}
                  stroke={link.type === 'blood' ? '#8a1c1c' : '#d4af37'}
                  strokeWidth="1.5"
                  strokeDasharray={link.type === 'blood' ? 'none' : '4 2'}
                  filter="url(#glow)"
                />
              );
            })}

            {/* Trunk paths */}
            <path d="M50,95 Q50,50 50,5" stroke="#1a120b" strokeWidth="0.5" fill="none" opacity="0.1" />
          </svg>

          {/* Character Nodes */}
          {LOTR_CHARACTERS.map(char => {
            const pos = TREE_POSITIONS[char.id];
            if (!pos) return null;

            return (
              <motion.div
                key={char.id}
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                whileHover={{ scale: 1.1, zIndex: 30 }}
                className="absolute transform -translate-x-1/2 -translate-y-1/2 cursor-pointer"
                style={{ left: `${pos.x}%`, top: `${pos.y}%` }}
                onClick={() => setSelectedChar(char)}
              >
                <div className="group relative">
                  {/* Portrait Frame (Medallion Style) */}
                  <div className={`
                    w-12 h-12 md:w-16 md:h-16 rounded-full border-2 overflow-hidden bg-white shadow-lg transition-all duration-500
                    ${char.faction === '黑暗势力' ? 'border-red-900 group-hover:shadow-red-500/50' : 'border-[#d4af37] group-hover:shadow-[#d4af37]/50'}
                  `}>
                    <GenerativeImage 
                        initialPrompt={char.imagePrompt}
                        alt={char.name}
                        stylePreset="LOTR_VINTAGE"
                        className="w-full h-full object-cover grayscale-[0.3] group-hover:grayscale-0"
                    />
                  </div>

                  {/* Name Label */}
                  <div className="absolute top-full left-1/2 -translate-x-1/2 mt-1 opacity-0 group-hover:opacity-100 transition-opacity bg-black/80 text-white px-2 py-0.5 rounded text-[10px] whitespace-nowrap z-40">
                    {char.name}
                  </div>
                </div>
              </motion.div>
            );
          })}
        </div>
      </div>

      {/* Detail Modal */}
      <AnimatePresence>
        {selectedChar && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#1a120b]/90 backdrop-blur-md"
            onClick={() => setSelectedChar(null)}
          >
            <motion.div
              initial={{ scale: 0.9, y: 30 }}
              animate={{ scale: 1, y: 0 }}
              exit={{ scale: 0.9, y: 30 }}
              className="bg-[#f4f1ea] w-full max-w-4xl rounded-sm shadow-2xl flex flex-col md:flex-row overflow-hidden relative border-[12px] border-[#1a120b] paper-texture"
              onClick={e => e.stopPropagation()}
            >
              <button onClick={() => setSelectedChar(null)} className="absolute top-4 right-4 z-50 text-white hover:rotate-90 transition-transform p-2 bg-black/40 rounded-full">
                <X size={20} />
              </button>

              <div className="w-full md:w-[45%] bg-[#1a120b] p-6 flex items-center justify-center">
                 <div className="w-full aspect-[3/4] border-[8px] border-white shadow-2xl overflow-hidden relative group">
                    <GenerativeImage 
                        initialPrompt={selectedChar.imagePrompt}
                        alt={selectedChar.name}
                        stylePreset="LOTR_VINTAGE"
                        className="w-full h-full object-cover"
                    />
                 </div>
              </div>

              <div className="w-full md:w-[55%] p-10 space-y-8 flex flex-col justify-center relative">
                 <div className="absolute inset-0 opacity-40 bg-[url('https://www.transparenttextures.com/patterns/natural-paper.png')] pointer-events-none"></div>

                 <div className="border-b-2 border-[#1a120b] pb-4 relative z-10">
                    <span className={`font-mono text-xs uppercase tracking-[0.4em] block mb-2 font-bold ${selectedChar.faction === '黑暗势力' ? 'text-red-900' : 'text-[#d4af37]'}`}>
                        {selectedChar.faction}
                    </span>
                    <h2 className="text-4xl md:text-5xl font-black text-[#1a120b] uppercase tracking-tighter font-title leading-tight">{selectedChar.name}</h2>
                 </div>

                 <div className="space-y-6 relative z-10">
                    <div className="space-y-3">
                        <div className="flex items-center gap-3">
                             <div className={`h-[2px] w-6 ${selectedChar.faction === '黑暗势力' ? 'bg-red-900' : 'bg-[#d4af37]'}`}></div>
                             <h5 className="font-bold text-[10px] uppercase tracking-widest text-[#1a120b]">The Record</h5>
                        </div>
                        <p className="text-xl leading-relaxed text-[#5c4d3c] font-hand italic">
                            "{selectedChar.description}"
                        </p>
                    </div>

                    <div className="pt-6 border-t border-black/10 flex items-center justify-between opacity-50">
                        <div className="flex gap-4">
                            <Sword size={18} />
                            <Shield size={18} />
                            <Map size={18} />
                        </div>
                        <span className="font-mono text-[9px] uppercase tracking-widest font-bold">Manuscript ID: {selectedChar.id.toUpperCase()}</span>
                    </div>
                 </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { LOTR_STORY } from '../constants';
import { LotRStoryPage } from '../types';
import { GenerativeImage } from './GenerativeImage';
