import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { LOTR_STORY } from '../constants';
import { LotRStoryPage } from '../types';
import { GenerativeImage } from './GenerativeImage';
import { ChevronLeft, ChevronRight, BookOpen, Languages } from 'lucide-react';

interface LotRStoryProps {
  part: 'part1' | 'part2' | 'part3';
}

export const LotRStory: React.FC<LotRStoryProps> = ({ part }) => {
  const pages = LOTR_STORY[part];
  const [currentPage, setCurrentPage] = useState(0);
  const [lang, setLang] = useState<'zh' | 'en'>('zh');

  const nextPage = () => setCurrentPage(prev => Math.min(prev + 1, pages.length - 1));
  const prevPage = () => setCurrentPage(prev => Math.max(prev - 1, 0));

  const page = pages[currentPage];
  const isSummary = page.id === 0;

  return (
    <div className="min-h-screen bg-[#1a0f05] flex items-center justify-center p-4 md:p-12 font-serif overflow-hidden relative">
      {/* Background paper texture */}
      <div className="absolute inset-0 opacity-10 pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/natural-paper.png')]"></div>

      <div className="max-w-7xl w-full h-[85vh] bg-[#c2a67e] shadow-[0_50px_100px_rgba(0,0,0,0.8)] rounded-sm flex flex-col md:flex-row relative overflow-hidden parchment-texture">

        {/* Language Toggle */}
        <button 
          onClick={() => setLang(l => l === 'zh' ? 'en' : 'zh')}
          className="absolute top-4 right-20 z-40 bg-[#1a120b] text-[#d4af37] px-3 py-1.5 rounded-full flex items-center gap-2 hover:scale-105 transition-all font-mono text-xs"
        >
          <Languages size={14} />
          {lang === 'zh' ? 'EN' : '中文'}
        </button>

        {/* Left Side: Illustration */}
        <div className="w-full md:w-[45%] h-1/2 md:h-full relative overflow-hidden border-r-2 border-black/10">
          <AnimatePresence mode="wait">
            <motion.div
              key={page.id}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 20 }}
              transition={{ duration: 0.8 }}
              className="absolute inset-0"
            >
              <GenerativeImage 
                initialPrompt={page.imagePrompt}
                alt={lang === 'zh' ? page.title : page.titleEn}
                stylePreset="LOTR_VINTAGE"
                className="w-full h-full object-cover grayscale-[0.1] hover:grayscale-0 transition-all cursor-pointer"
              />
              <div className="absolute inset-0 bg-gradient-to-r from-black/30 via-transparent to-black/20 pointer-events-none"></div>
            </motion.div>
          </AnimatePresence>
        </div>

        {/* Right Side: Narrative Content */}
        <div className="w-full md:w-[55%] h-1/2 md:h-full p-8 md:p-16 flex flex-col relative overflow-y-auto scrollbar-vintage">
          <AnimatePresence mode="wait">
            <motion.div
              key={`${page.id}-${lang}`}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="flex flex-col h-full"
            >
              <div className="space-y-6 mb-8">
                <div className="flex items-center gap-3 text-[#5c4d3c] border-b border-black/10 pb-2">
                    <BookOpen size={18} />
                    <span className="font-mono text-xs uppercase tracking-[0.4em] font-bold">
                        {isSummary ? (lang === 'zh' ? '序言' : 'Prologue') : `MS-0${page.id}`}
                    </span>
                </div>
                <h2 className={`
                  ${lang === 'en' ? 'font-uncial tracking-normal' : 'font-title tracking-tighter'}
                  text-3xl md:text-5xl font-black text-[#1a120b] uppercase leading-tight drop-shadow-sm
                `}>
                  {lang === 'zh' ? page.title : page.titleEn}
                </h2>
              </div>

              <div className="flex-1">
                <p className={`
                  ${lang === 'zh' ? 'text-2xl tracking-wide' : 'text-xl leading-relaxed font-fantasy italic'}
                  text-[#2c1e13] font-hand first-letter:text-7xl first-letter:font-title first-letter:mr-3 first-letter:float-left first-letter:text-[#8a1c1c]
                `}>
                  {lang === 'zh' ? page.content : page.contentEn}
                </p>
              </div>

              {/* Page Numbering Decor */}
              <div className="mt-12 flex justify-between items-center opacity-40 border-t border-black/10 pt-4">
                  <span className="font-mono text-[10px] uppercase tracking-widest">Chronicle of the Third Age</span>
                  <span className="font-title text-sm">{currentPage + 1} / {pages.length}</span>
              </div>
            </motion.div>
          </AnimatePresence>

          {/* Controls */}
          <div className="absolute bottom-8 right-8 flex gap-4 z-20">
            <button 
                onClick={prevPage}
                disabled={currentPage === 0}
                className="p-4 bg-[#1a120b] text-[#c2a67e] rounded-full disabled:opacity-30 hover:bg-[#d4af37] hover:text-[#1a120b] transition-all shadow-xl active:scale-95"
            >
              <ChevronLeft size={28} />
            </button>
            <button 
                onClick={nextPage}
                disabled={currentPage === pages.length - 1}
                className="p-4 bg-[#1a120b] text-[#c2a67e] rounded-full disabled:opacity-30 hover:bg-[#d4af37] hover:text-[#1a120b] transition-all shadow-xl active:scale-95"
            >
              <ChevronRight size={28} />
            </button>
          </div>

          <div className="absolute left-0 top-0 bottom-0 w-12 bg-gradient-to-r from-black/20 to-transparent pointer-events-none"></div>
        </div>
      </div>

      {/* Floating Header */}
      <div className="fixed top-8 left-1/2 -translate-x-1/2 z-30">
           <span className={`
                ${lang === 'en' ? 'font-fantasy' : 'font-mono'}
                text-[10px] uppercase tracking-[0.5em] text-[#d4af37] bg-black/60 px-6 py-2 rounded-full backdrop-blur-sm border border-[#d4af37]/30 shadow-2xl
           `}>
              {part === 'part1' ? (lang === 'zh' ? '卷一：护戒同盟' : 'Book I: The Fellowship') 
               : part === 'part2' ? (lang === 'zh' ? '卷二：双塔奇兵' : 'Book II: The Two Towers') 
               : (lang === 'zh' ? '卷三：王者归来' : 'Book III: Return of the King')}
           </span>
      </div>

      <style>{`
        .scrollbar-vintage::-webkit-scrollbar {
          width: 4px;
        }
        .scrollbar-vintage::-webkit-scrollbar-track {
          background: rgba(0,0,0,0.05);
        }
        .scrollbar-vintage::-webkit-scrollbar-thumb {
          background: #1a120b;
        }
      `}</style>
    </div>
  );
};

