                                    {selectedNode.alignment === 'mixed' ? 'Split (Red/Black)' 
                                     : selectedNode.alignment === 'red' ? 'Government Class'
                                     : selectedNode.alignment === 'black' ? 'Religious Conservative'
                                     : 'Proletariat'}
                                 </span>
                             </div>
                        </div>
                    </div>
                </div>
            </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { ViewState } from './types';
import { BookCover } from './components/BookCover';
import { Timeline } from './components/Timeline';
import { FamilyTree } from './components/FamilyTree';
import { RedBlackJourney } from './components/RedBlackJourney';
import { JulienNetwork } from './components/JulienNetwork';
import { LotRHub } from './components/LotRHub';
import { LotRCharacters } from './components/LotRCharacters';
import { LotRStory } from './components/LotRStory';
import { Library } from './components/Library';
import { AmbientSound } from './components/AmbientSound';
import { GitBranch, History, BookOpen, Library as LibraryIcon, Network, BrainCircuit, Users, Compass } from 'lucide-react';
import { BOOKS } from './constants';

const App: React.FC = () => {
  // Default to 100years intro instead of library
  const [view, setView] = useState<ViewState>(ViewState.INTRO);
  const [currentBookId, setCurrentBookId] = useState<string | null>('100years');

  const currentBook = BOOKS.find(b => b.id === currentBookId) || null;

  const handleSelectBook = (bookId: string) => {
    setCurrentBookId(bookId);
    setView(ViewState.INTRO);
  };

  const handleBackToLibrary = () => {
      setView(ViewState.LIBRARY);
      setCurrentBookId(null);
  };

  const renderContent = () => {
    if (view === ViewState.LIBRARY) {
        return <Library onSelectBook={handleSelectBook} />;
    }

    if (view === ViewState.INTRO) {
        return <BookCover book={currentBook} onOpen={() => {
            if (currentBookId === '100years') setView(ViewState.TIMELINE);
            if (currentBookId === 'red_black') setView(ViewState.JULIEN_JOURNEY);
            if (currentBookId === 'lotr') setView(ViewState.LOTR_HUB);
        }} onBack={handleBackToLibrary} />;
    }

    // 100 Years Logic
    if (currentBookId === '100years') {
        switch (view) {
            case ViewState.TIMELINE: return <Timeline />;
            case ViewState.FAMILY_TREE: return <FamilyTree />;
            default: return <Timeline />;
        }
    }

    // Red & Black Logic
    if (currentBookId === 'red_black') {
        switch (view) {
            case ViewState.JULIEN_JOURNEY: return <RedBlackJourney />;
            case ViewState.JULIEN_NETWORK: return <JulienNetwork />;
            default: return <RedBlackJourney />;
        }
    }

    // LOTR Logic
    if (currentBookId === 'lotr') {
        switch (view) {
            case ViewState.LOTR_HUB: return <LotRHub onNavigate={setView} />;
            case ViewState.LOTR_CHARACTERS: return <LotRCharacters />;
            case ViewState.LOTR_STORY_1: return <LotRStory part="part1" />;
            case ViewState.LOTR_STORY_2: return <LotRStory part="part2" />;
            case ViewState.LOTR_STORY_3: return <LotRStory part="part3" />;
            default: return <LotRHub onNavigate={setView} />;
        }
    }

    return <Library onSelectBook={handleSelectBook} />;
  };

  const renderNav = () => {
    if (view === ViewState.LIBRARY || view === ViewState.INTRO) return null;

    const isLOTR = currentBookId === 'lotr';
    const isRedBlack = currentBookId === 'red_black';
    const is100Years = currentBookId === '100years';

    const navBg = isRedBlack ? 'bg-black text-white' : isLOTR ? 'bg-[#1a120b] text-[#d4af37]' : 'bg-[#2c241b] text-[#e3dcd2]';
    const hoverBg = isRedBlack ? 'hover:bg-gray-800' : 'hover:bg-white/10';
    const activeBg = isRedBlack ? 'bg-gray-800' : 'bg-white/10';
    const titleColor = isRedBlack ? 'text-black' : isLOTR ? 'text-[#d4af37]' : 'text-[#2c241b]';

    return (
        <nav className="fixed top-0 inset-x-0 z-40 p-4 flex justify-between items-start pointer-events-none">
          <div className={`pointer-events-auto p-1 rounded-sm shadow-lg flex gap-1 ${navBg}`}>
             <button 
                onClick={handleBackToLibrary}
                className={`p-2 rounded-sm transition-colors ${hoverBg}`}
                title="Back to Library"
             >
                <LibraryIcon size={20} />
             </button>
             <div className="w-[1px] bg-white/20 mx-1"></div>
             <button 
                onClick={() => setView(ViewState.INTRO)}
                className={`p-2 rounded-sm transition-colors ${hoverBg} ${view === ViewState.INTRO ? activeBg : ''}`}
                title="Cover"
             >
                <BookOpen size={20} />
             </button>

             {is100Years && (
                <>
                    <button 
                        onClick={() => setView(ViewState.TIMELINE)}
                        className={`p-2 rounded-sm transition-colors ${hoverBg} ${view === ViewState.TIMELINE ? activeBg : ''}`}
                        title="Timeline"
                    >
                        <History size={20} />
                    </button>
                    <button 
                        onClick={() => setView(ViewState.FAMILY_TREE)}
                        className={`p-2 rounded-sm transition-colors ${hoverBg} ${view === ViewState.FAMILY_TREE ? activeBg : ''}`}
                        title="Family Tree"
                    >
                        <GitBranch size={20} />
                    </button>
                </>
             )}

             {isRedBlack && (
                <>
                    <button 
                        onClick={() => setView(ViewState.JULIEN_JOURNEY)}
                        className={`p-2 rounded-sm transition-colors ${hoverBg} ${view === ViewState.JULIEN_JOURNEY ? activeBg : ''}`}
                        title="Julien's Journey"
                    >
                        <BrainCircuit size={20} />
                    </button>
                    <button 
                        onClick={() => setView(ViewState.JULIEN_NETWORK)}
                        className={`p-2 rounded-sm transition-colors ${hoverBg} ${view === ViewState.JULIEN_NETWORK ? activeBg : ''}`}
                        title="Character Network"
                    >
                        <Network size={20} />
                    </button>
                </>
             )}

             {isLOTR && (
                <>
                    <button 
                        onClick={() => setView(ViewState.LOTR_HUB)}
                        className={`p-2 rounded-sm transition-colors ${hoverBg} ${view === ViewState.LOTR_HUB ? activeBg : ''}`}
                        title="The Chronicles Hub"
                    >
                        <Compass size={20} />
                    </button>
                    <button 
                        onClick={() => setView(ViewState.LOTR_CHARACTERS)}
                        className={`p-2 rounded-sm transition-colors ${hoverBg} ${view === ViewState.LOTR_CHARACTERS ? activeBg : ''}`}
                        title="Characters"
                    >
                        <Users size={20} />
                    </button>
                </>
             )}
          </div>

          <div className={`pointer-events-auto p-2 rounded border shadow-sm max-w-[150px] text-right bg-white/90 ${isRedBlack ? 'border-black' : isLOTR ? 'border-[#d4af37]' : 'border-[#8a7a5f]'}`}>
             <h1 className={`font-title text-sm font-bold ${titleColor}`}>
                {currentBook?.title}
             </h1>
             <p className="font-mono text-[10px] text-gray-500 opacity-80">
                {is100Years ? 'Macondo' : isRedBlack ? 'Verrières' : 'Middle-earth'}
             </p>
          </div>
        </nav>
    );
  };

  return (
    <div className={`min-h-screen relative ${currentBookId === '100years' || !currentBookId ? 'paper-texture' : currentBookId === 'lotr' ? 'bg-[#1a120b]' : 'bg-[#e5e5e5]'}`}>
      {currentBookId === '100years' && view !== ViewState.LIBRARY && (
        <AmbientSound />
      )}
      {renderNav()}
      <main className="min-h-screen">
        {renderContent()}
      </main>
      {(currentBookId === '100years' || !currentBookId) && (
        <div className="fixed inset-0 border-[12px] border-transparent pointer-events-none z-40 mix-blend-multiply" 
            style={{ boxShadow: 'inset 0 0 100px rgba(44, 36, 27, 0.2)' }}>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { LOTR_STORY } from '../constants';
import { LotRStoryPage } from '../types';
import { GenerativeImage } from './GenerativeImage';
import { ChevronLeft, ChevronRight, BookOpen, Languages } from 'lucide-react';

interface LotRStoryProps {
  part: 'part1' | 'part2' | 'part3';
}

export const LotRStory: React.FC<LotRStoryProps> = ({ part }) => {
  const pages = LOTR_STORY[part];
  const [currentPage, setCurrentPage] = useState(0);
  const [lang, setLang] = useState<'zh' | 'en'>('zh');
  const [embers, setEmbers] = useState<{id: number, left: string, delay: string}[]>([]);

  useEffect(() => {
    // Generate some random embers for the effect
    const newEmbers = Array.from({length: 15}).map((_, i) => ({
      id: i,
      left: `${Math.random() * 100}%`,
      delay: `${Math.random() * 3}s`
    }));
    setEmbers(newEmbers);
  }, []);

  const nextPage = () => setCurrentPage(prev => Math.min(prev + 1, pages.length - 1));
  const prevPage = () => setCurrentPage(prev => Math.max(prev - 1, 0));

  const page = pages[currentPage];
  const isSummary = page.id === 0;

  return (
    <div className="min-h-screen bg-[#1a0f05] flex items-center justify-center p-4 md:p-12 font-serif overflow-hidden relative">
      <div className="absolute inset-0 opacity-10 pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/natural-paper.png')]"></div>

      <div className="max-w-7xl w-full h-[85vh] bg-[#6d4a9e] shadow-[0_50px_100px_rgba(0,0,0,0.8)] rounded-sm flex flex-col md:flex-row relative overflow-hidden burning-card">

        {/* Burning Effect Layers */}
        <div className="burning-edge"></div>
        {embers.map(e => (
          <div key={e.id} className="ember" style={{left: e.left, animationDelay: e.delay}}></div>
        ))}

        {/* Language Toggle */}
        <button 
          onClick={() => setLang(l => l === 'zh' ? 'en' : 'zh')}
          className="absolute top-4 right-20 z-40 bg-[#1a120b] text-[#d4af37] px-3 py-1.5 rounded-full flex items-center gap-2 hover:scale-105 transition-all font-mono text-xs shadow-lg"
        >
          <Languages size={14} />
          {lang === 'zh' ? 'EN' : '中文'}
        </button>

        {/* Left Side: Illustration */}
        <div className="w-full md:w-[45%] h-1/2 md:h-full relative overflow-hidden border-r-2 border-black/20">
          <AnimatePresence mode="wait">
            <motion.div
              key={page.id}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 20 }}
              transition={{ duration: 0.8 }}
              className="absolute inset-0"
            >
              <GenerativeImage 
                initialPrompt={page.imagePrompt}
                alt={lang === 'zh' ? page.title : page.titleEn}
                stylePreset="LOTR_VINTAGE"
                className="w-full h-full object-cover"
              />
              <div className="absolute inset-0 bg-gradient-to-r from-black/50 via-transparent to-black/30 pointer-events-none"></div>
            </motion.div>
          </AnimatePresence>
        </div>

        {/* Right Side: Narrative Content */}
        <div className="w-full md:w-[55%] h-1/2 md:h-full p-8 md:p-16 flex flex-col relative overflow-y-auto scrollbar-vintage z-10">
          <AnimatePresence mode="wait">
            <motion.div
              key={`${page.id}-${lang}`}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="flex flex-col h-full"
            >
              <div className="space-y-6 mb-8">
                <div className="flex items-center gap-3 text-white/50 border-b border-white/10 pb-2">
                    <BookOpen size={18} />
                    <span className="font-mono text-xs uppercase tracking-[0.4em] font-bold">
                        {isSummary ? (lang === 'zh' ? '序言' : 'Prologue') : `RECORD-0${page.id}`}
                    </span>
                </div>
                <h2 className={`
                  ${lang === 'en' ? 'font-uncial tracking-normal' : 'font-title tracking-tighter'}
                  text-3xl md:text-5xl font-black text-white uppercase leading-tight drop-shadow-xl burning-text
                `}>
                  {lang === 'zh' ? page.title : page.titleEn}
                </h2>
              </div>

              <div className="flex-1">
                <p className={`
                  ${lang === 'zh' ? 'text-2xl tracking-wide' : 'text-xl leading-relaxed font-fantasy italic'}
                  text-white/90 first-letter:text-7xl first-letter:font-title first-letter:mr-3 first-letter:float-left first-letter:text-[#ff6600] first-letter:drop-shadow-[0_0_10px_rgba(255,102,0,0.5)]
                `}>
                  {lang === 'zh' ? page.content : page.contentEn}
                </p>
              </div>

              <div className="mt-12 flex justify-between items-center opacity-30 border-t border-white/10 pt-4 text-white">
                  <span className="font-mono text-[10px] uppercase tracking-widest">Chronicle of the Third Age</span>
                  <span className="font-title text-sm">{currentPage + 1} / {pages.length}</span>
              </div>
            </motion.div>
          </AnimatePresence>

          {/* Controls */}
          <div className="absolute bottom-8 right-8 flex gap-4 z-20">
            <button 
                onClick={prevPage}
                disabled={currentPage === 0}
                className="p-4 bg-white/10 text-white rounded-full disabled:opacity-10 hover:bg-[#ff6600] hover:text-black transition-all shadow-xl backdrop-blur-md"
            >
              <ChevronLeft size={28} />
            </button>
            <button 
                onClick={nextPage}
                disabled={currentPage === pages.length - 1}
                className="p-4 bg-white/10 text-white rounded-full disabled:opacity-10 hover:bg-[#ff6600] hover:text-black transition-all shadow-xl backdrop-blur-md"
            >
              <ChevronRight size={28} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

