            if (!startNode || !endNode) return null;

            const x1 = viewMode === 'SOCIAL' ? startNode.socialX ?? startNode.x : startNode.x;
            const y1 = viewMode === 'SOCIAL' ? startNode.socialY ?? startNode.y : startNode.y;
