export const LotRPersonalityTest: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [currentStep, setCurrentStep] = useState<'START' | 'QUIZ' | 'RESULT'>('START');
  const [qIndex, setQIndex] = useState(0);
  const [scores, setScores] = useState<Record<string, number>>({});
  const [resultChar, setResultChar] = useState<Character | null>(null);

  const handleStart = () => {
    setScores({});
    setQIndex(0);
    setCurrentStep('QUIZ');
  };

  const handleSelect = (traits: string[]) => {
    const newScores = { ...scores };
    traits.forEach(t => {
      newScores[t] = (newScores[t] || 0) + 1;
    });
    setScores(newScores);

    if (qIndex < QUESTIONS.length - 1) {
      setQIndex(qIndex + 1);
    } else {
      calculateResult(newScores);
    }
  };

  const calculateResult = (finalScores: Record<string, number>) => {
    // Basic logic: find character whose traits/type/faction matches most high scores
    let bestMatch = LOTR_CHARACTERS[0];
    let maxOverlap = -1;

    LOTR_CHARACTERS.forEach(char => {
      let overlap = 0;
      // Check type and faction matches
      if (finalScores[char.type]) overlap += finalScores[char.type] * 2;
      if (finalScores[char.faction || ""]) overlap += finalScores[char.faction || ""] * 2;

      // Bonus based on general vibe/description matches
      if (char.description.includes("智慧") && finalScores["智慧"]) overlap++;
      if (char.description.includes("忠诚") && finalScores["忠诚"]) overlap++;
      if (char.description.includes("力量") && finalScores["力量"]) overlap++;

      if (overlap > maxOverlap) {
        maxOverlap = overlap;
        bestMatch = char;
      }
    });

    setResultChar(bestMatch);
    setCurrentStep('RESULT');
  };

  return (
    <div className="min-h-screen lotr-dark-bg flex items-center justify-center p-4 md:p-12 font-serif overflow-hidden relative">
      {/* Background Particles */}
