                            <div className="h-[1px] w-24 bg-[#1a120b]/20 mx-auto shadow-sm"></div>

                            <motion.button
                                whileHover={{ scale: 1.05 }}
                                whileTap={{ scale: 0.95 }}
                                className="inline-flex items-center gap-2 bg-[#1a120b] text-[#d4af37] px-6 py-2 rounded-sm font-mono text-[10px] md:text-xs font-bold uppercase tracking-widest border border-[#d4af37]/30 shadow-lg"
                                onClick={(e) => {
                                    e.stopPropagation();
                                    onNavigate(sections[activeSection].id);
                                }}
                            >
                                Enter Chronicle
                                <ArrowRight size={14} />
                            </motion.button>

                            <p className="text-[9px] md:text-[10px] font-mono italic text-gray-600 font-bold tracking-[0.2em] uppercase leading-relaxed mt-4">
                                {sections[activeSection].quote}
                            </p>
                        </div>
                    </motion.div>
                ) : (
                    <div className="h-full flex flex-col items-center justify-center opacity-20 gap-4">
                        <MousePointer2 className="w-12 h-12 md:w-16 md:h-16 text-[#1a120b]" />
                        <p className="text-xs md:text-sm font-hand uppercase tracking-widest">Select a Chronicle</p>
                    </div>
                )}
            </AnimatePresence>
        </div>
      </motion.div>
    </div>
  );
};

