import { get, set, del, clear, keys } from 'idb-keyval';

const PREFIX = 'mm_img_';

/**
 * Robust key generator that avoids btoa's character set limitations.
 * Uses a simple hash-like string from the prompt to ensure safe IndexedDB keys.
 */
const formatKey = (prompt: string) => {
  // Use a simple string cleaning + hash for the key
  // btoa fails on non-ASCII characters, which prompts often have.
  const cleanPrompt = prompt.slice(0, 200).replace(/[^a-zA-Z0-0]/g, '_');
  let hash = 0;
  for (let i = 0; i < prompt.length; i++) {
    const char = prompt.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32bit integer
  }
  return `${PREFIX}${cleanPrompt}_${Math.abs(hash)}`;
};

/**
 * Wraps an IndexedDB action with basic retry logic to handle 
 * "database connection is closing" or other transient errors.
 */
async function withRetry<T>(action: () => Promise<T>, retries = 2): Promise<T | undefined> {
  try {
    return await action();
  } catch (e: any) {
    const isClosing = 
      e?.message?.includes('connection is closing') || 
      e?.name === 'InvalidStateError' || 
      e?.name === 'TransactionInactiveError';

    if (isClosing && retries > 0) {
      // Wait a tiny bit for the connection state to settle/reset
      await new Promise(resolve => setTimeout(resolve, 150));
      return withRetry(action, retries - 1);
    }

    // If connection is broken or retries failed, log and gracefully fail (returning undefined/miss)
    if (isClosing) {
      console.debug('IndexedDB connection lost or closing. Bypassing cache.');
      return undefined;
    }

    throw e;
  }
}

export const saveImageToStorage = async (prompt: string, base64Data: string) => {
  const key = formatKey(prompt);
  try {
    await withRetry(() => set(key, base64Data));
    console.debug('Image saved to storage:', key);
  } catch (e) {
    console.warn('Failed to save image to storage:', e);
  }
};

export const getImageFromStorage = async (prompt: string): Promise<string | undefined> => {
  const key = formatKey(prompt);
  try {
    return await withRetry(() => get(key));
  } catch (e) {
    console.warn('Failed to retrieve image from storage:', e);
    return undefined;
  }
};

export const clearImageCache = async () => {
  try {
    await withRetry(() => clear());
    console.log('Storage cleared');
  } catch (e) {
    console.error('Failed to clear storage:', e);
  }
};

export const getStorageUsage = async (): Promise<string> => {
  try {
    const allKeys = await withRetry(() => keys()) as any[] | undefined;
    if (!allKeys) return '0.00 MB';

    let totalSize = 0;
    for (const key of allKeys) {
        const val = await get(key);
        if (typeof val === 'string') {
            totalSize += val.length * 2; // Approx bytes for UTF-16 string
        }
    }
    return (totalSize / 1024 / 1024).toFixed(2) + ' MB';
  } catch (e) {
    console.error('Failed to calculate storage usage:', e);
    return 'Unknown';
  }
};

