export const Timeline: React.FC = () => {
  const [revealedCount, setRevealedCount] = useState(1);

  const revealNext = () => {
    if (revealedCount < STORY_PHASES.length) {
      setRevealedCount(prev => prev + 1);
      setTimeout(() => {
        window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
      }, 100);
    }
  };

  return (
    <div className="max-w-4xl mx-auto py-20 px-6 space-y-32 pb-60">
      <div className="text-center space-y-8 mb-24">
        <ScrollText className="mx-auto text-[#5c4d3c] opacity-40" size={48} />
        <h2 className="font-title text-5xl text-[#2c241b] tracking-tighter">THE MANUSCRIPTS OF MACONDO</h2>
        <p className="font-hand text-2xl text-[#5c4d3c] max-w-2xl mx-auto leading-relaxed">
          The history of the family was a machine of unavoidable repetitions, a wheel that would have gone on spinning into eternity...
        </p>
      </div>

      <div className="space-y-40 relative">
        {/* Vertical Hand-drawn Vine Line */}
        <div className="absolute left-1/2 -translate-x-1/2 top-0 bottom-0 w-1 bg-[#5c4d3c]/10 z-0"></div>

        {STORY_PHASES.slice(0, revealedCount).map((phase, index) => (
          <motion.div 
            key={phase.id}
            initial={{ opacity: 0, y: 50 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className={`flex flex-col ${index % 2 === 0 ? 'md:flex-row' : 'md:flex-row-reverse'} items-center gap-12 md:gap-20 relative z-10`}
          >
            {/* Visual Part */}
            <div className="w-full md:w-1/2">
                <div className="relative group">
                    {/* Shadow Layer */}
                    <div className="absolute inset-0 bg-black/10 translate-x-4 translate-y-4 rounded-sm rotate-2 group-hover:rotate-0 transition-transform"></div>
                    <div className="bg-white p-4 shadow-2xl border border-black/5 rotate-[-2deg] group-hover:rotate-0 transition-transform duration-700">
                        <GenerativeImage 
                            initialPrompt={phase.imagePrompt}
                            alt={phase.title}
                            stylePreset="RUSTY_LAKE"
                            className="w-full aspect-video md:aspect-square object-cover grayscale-[0.3] group-hover:grayscale-0 transition-all duration-1000"
                        />
                    </div>
                    {/* Hand-drawn number */}
                    <div className="absolute -top-6 -left-6 w-16 h-16 bg-[#2c241b] text-[#e3dcd2] rounded-full flex items-center justify-center font-hand text-3xl border-4 border-[#e3dcd2] shadow-xl">
                        {phase.id}
                    </div>
                </div>
            </div>

            {/* Content Part */}
            <div className="w-full md:w-1/2 space-y-6 text-center md:text-left">
                <header className="border-b-2 border-black/10 pb-4">
                    <h3 className="font-title text-3xl md:text-4xl text-[#1a120b] leading-tight uppercase tracking-tight">
                        {phase.title}
                    </h3>
                </header>
                <div className="paper-texture p-6 bg-[#f2efe9]/40 rounded-sm">
                    <p className="font-hand text-2xl md:text-3xl text-[#2c1a0a] leading-[1.6] italic">
                        {phase.description}
                    </p>
                </div>
            </div>
          </motion.div>
        ))}
      </div>

      {revealedCount < STORY_PHASES.length && (
        <div className="flex justify-center pt-20">
            <motion.button 
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
                onClick={revealNext}
                className="flex flex-col items-center gap-4 text-[#5c4d3c] font-hand text-xl hover:text-[#1a120b] transition-colors"
            >
                <span>Unroll the next scroll...</span>
                <div className="w-16 h-16 rounded-full border-2 border-[#5c4d3c]/40 flex items-center justify-center animate-bounce">
                    <ArrowDown size={32} />
                </div>
            </motion.button>
        </div>
      )}
    </div>
  );
};

