            <h2 className="font-title text-5xl text-[#2c241b] tracking-[0.2em] uppercase drop-shadow-sm">The Lineage of Solitude</h2>
            <p className="font-hand text-2xl text-[#5c4d3c] italic">"Everything was written on Melquíades' parchments..."</p>
            <div className="h-1 w-32 bg-[#2c241b] mx-auto opacity-20"></div>
        </header>

        {/* Generational Clusters as Scattered Notes */}
        <div className="space-y-48">
            {generations.map(gen => {
                const chars = BUENDIA_FAMILY.filter(c => c.generation === gen);
                if (chars.length === 0) return null;

                return (
                    <div key={gen} className="relative">
                        {/* Generation Header in Handwriting */}
                        <div className="absolute -top-16 left-0 font-hand text-2xl text-[#8a7a5f] border-b-2 border-[#8a7a5f]/30 pr-12">
