                                        <div className="w-32 h-32 md:w-48 md:h-48 overflow-hidden relative grayscale group-hover:grayscale-0 transition-all duration-1000">
                                            <GenerativeImage 
                                                initialPrompt={char.imagePrompt}
                                                alt={char.name}
                                                stylePreset="RUSTY_LAKE"
                                                className="w-full h-full object-cover"
