                                            <div className="absolute inset-0 bg-sepia mix-blend-multiply opacity-20 pointer-events-none"></div>
                                            <div className="absolute inset-0 ring-inset ring-1 ring-black/10 pointer-events-none"></div>
                                        </div>

                                        <div className="absolute bottom-3 left-0 right-0 text-center">
                                            <span className="font-hand text-xl text-black font-bold block px-2 leading-none">
                                                {char.name}
                                            </span>
                                        </div>
                                    </div>

                                    {/* Connection Symbols */}
                                    {char.parents && (
                                        <div className="absolute -top-10 text-[#5c4d3c]/30 group-hover:text-[#8b0000] transition-colors">
                                            <LinkIcon size={20} />
                                        </div>
                                    )}
