                            ))}
                        </div>
                    </div>
                );
            })}
        </div>
      </div>

      <AnimatePresence>
        {selectedChar && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-[#1a120b]/90 backdrop-blur-sm" onClick={() => setSelectedChar(null)}>
                <motion.div 
                    initial={{ scale: 0.8, opacity: 0, y: 50 }}
                    animate={{ scale: 1, opacity: 1, y: 0 }}
                    exit={{ scale: 0.8, opacity: 0, y: 50 }}
                    className="bg-[#f2efe9] max-w-4xl w-full p-1 shadow-[0_40px_100px_rgba(0,0,0,0.6)] border-2 border-[#2c241b] relative"
