                                <div className="absolute inset-0 border-8 border-white/40 pointer-events-none"></div>
                            </div>
                            <div className="mt-8 font-mono text-[10px] uppercase tracking-widest text-[#8a7a5f] bg-black/5 px-4 py-2">
                                Manuscript Ref: {selectedChar.id.toUpperCase()}
                            </div>
                        </div>

                        <div className="w-full md:w-3/5 space-y-8">
                            <header className="border-b-2 border-black/10 pb-6">
                                <h3 className="font-title text-4xl text-[#1a120b] leading-none mb-2">{selectedChar.name}</h3>
                                <p className="font-hand text-2xl text-[#8a7a5f] italic">{selectedChar.relation}</p>
                            </header>

                            <div className="space-y-6">
                                <p className="font-hand text-2xl leading-relaxed text-[#2c1a0a] italic">
                                    "{selectedChar.description}"
                                </p>

                                <div className="grid grid-cols-2 gap-6 pt-6 font-mono text-xs text-[#5c4d3c]">
                                    {selectedChar.partner && (
                                        <div className="space-y-1">
                                            <span className="font-black uppercase block opacity-40">Tethered Soul:</span>
                                            <span className="font-bold border-b border-black/10 pb-1">{selectedChar.partner}</span>
                                        </div>
                                    )}
                                    {selectedChar.parents && (
                                        <div className="space-y-1">
                                            <span className="font-black uppercase block opacity-40">Lineage Origin:</span>
                                            <span className="font-bold border-b border-black/10 pb-1">{selectedChar.parents.join(' & ')}</span>
                                        </div>
                                    )}
                                </div>
                            </div>

                            <div className="pt-10 flex justify-end">
                                <span className="font-title text-5xl opacity-5 select-none uppercase tracking-tighter">BUENDIA</span>
                            </div>
                        </div>
                    </div>
                </motion.div>
            </div>
        )}
      </AnimatePresence>
    </div>
  );
};

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { STORY_PHASES } from '../constants';
import { GenerativeImage } from './GenerativeImage';
import { ArrowDown, ScrollText, Feather } from 'lucide-react';

export const Timeline: React.FC = () => {
  const [revealedCount, setRevealedCount] = useState(1);

  const revealNext = () => {
    if (revealedCount < STORY_PHASES.length) {
      setRevealedCount(prev => prev + 1);
      setTimeout(() => {
        window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
      }, 100);
    }
  };

  return (
    <div className="relative min-h-screen bg-[#e3dcd2] paper-texture pb-60 overflow-x-hidden">
      {/* Scroll Background Element */}
      <div className="absolute left-1/2 -translate-x-1/2 top-0 bottom-0 w-full max-w-4xl bg-[#f2efe9]/40 border-x border-[#5c4d3c]/10 z-0"></div>

      <div className="max-w-4xl mx-auto py-24 px-6 relative z-10 space-y-32">
        <header className="text-center space-y-8 mb-40">
            <motion.div 
                initial={{ rotate: -10, opacity: 0 }}
                animate={{ rotate: 0, opacity: 1 }}
                className="inline-block p-4 bg-white/50 border border-[#5c4d3c]/20 shadow-lg"
            >
                <ScrollText className="text-[#5c4d3c]" size={40} />
            </motion.div>
            <h2 className="font-title text-5xl text-[#2c241b] tracking-tighter uppercase">Chronicles of Solitude</h2>
            <p className="font-hand text-2xl text-[#5c4d3c] max-w-2xl mx-auto leading-relaxed italic opacity-80">
                "The history of the family was a machine of unavoidable repetitions..."
            </p>
            <div className="flex justify-center gap-4">
                <div className="h-px w-20 bg-[#5c4d3c]/20 my-auto"></div>
                <Feather size={16} className="text-[#8a7a5f]" />
                <div className="h-px w-20 bg-[#5c4d3c]/20 my-auto"></div>
            </div>
        </header>

        <div className="space-y-56 relative">
            {/* Hand-drawn Vertical Vine/Line */}
            <div className="absolute left-1/2 -translate-x-1/2 top-0 bottom-0 w-1 bg-gradient-to-b from-[#5c4d3c]/20 via-[#5c4d3c]/5 to-transparent z-0"></div>

            {STORY_PHASES.slice(0, revealedCount).map((phase, index) => (
              <motion.div 
                key={phase.id}
                initial={{ opacity: 0, y: 100 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true, margin: "-100px" }}
                className={`flex flex-col ${index % 2 === 0 ? 'md:flex-row' : 'md:flex-row-reverse'} items-center gap-16 md:gap-24 relative z-10`}
              >
                {/* Visual Clipping */}
                <div className="w-full md:w-1/2 relative group">
                    <div className="absolute -inset-4 bg-black/5 rounded-sm -rotate-2 group-hover:rotate-0 transition-transform"></div>
                    <div className="bg-white p-4 shadow-2xl border border-black/5 rotate-1 group-hover:rotate-0 transition-transform duration-700 relative">
                        {/* Paper tape top */}
                        <div className="absolute -top-3 left-1/2 -translate-x-1/2 w-20 h-6 bg-[#e3dcd2]/80 shadow-sm border border-black/5 rotate-1"></div>

                        <div className="w-full aspect-square overflow-hidden">
                            <GenerativeImage 
                                initialPrompt={phase.imagePrompt}
                                alt={phase.title}
                                stylePreset="RUSTY_LAKE"
                                className="w-full h-full object-cover grayscale-[0.4] group-hover:grayscale-0 transition-all duration-1000"
                            />
                        </div>
                    </div>
                    {/* Hand-drawn Phase Number */}
                    <div className="absolute -top-10 -left-10 md:-left-12 w-20 h-20 bg-[#2c241b] text-[#e3dcd2] rounded-full flex items-center justify-center font-hand text-4xl border-[6px] border-[#e3dcd2] shadow-2xl rotate-[-12deg]">
                        {phase.id}
                    </div>
                </div>

                {/* Narrative Parchment */}
                <div className="w-full md:w-1/2 space-y-6 text-center md:text-left">
                    <h3 className="font-title text-3xl text-[#1a120b] uppercase tracking-tighter border-b-2 border-black/5 pb-2 inline-block">
                        {phase.title}
                    </h3>
                    <div className="relative">
                        {/* Decorative Ink Splatter (Simulated with div) */}
                        <div className="absolute -top-8 -right-8 w-16 h-16 bg-[#5c4d3c]/5 rounded-full blur-2xl pointer-events-none"></div>

                        <p className="font-hand text-2xl md:text-3xl text-[#2c1a0a] leading-[1.6] italic">
                            {phase.description}
                        </p>
                    </div>
                </div>
              </motion.div>
            ))}
        </div>

        {revealedCount < STORY_PHASES.length && (
            <div className="flex justify-center pt-32">
                <motion.button 
                    whileHover={{ scale: 1.1, y: 10 }}
                    whileTap={{ scale: 0.9 }}
                    onClick={revealNext}
                    className="flex flex-col items-center gap-6 text-[#5c4d3c] font-hand text-2xl group"
                >
                    <span className="opacity-60 group-hover:opacity-100 transition-opacity">Unroll more of the prophecy...</span>
                    <div className="w-20 h-20 rounded-full border-2 border-[#5c4d3c]/20 flex items-center justify-center animate-bounce shadow-inner">
                        <ArrowDown size={40} className="opacity-40" />
                    </div>
                </motion.button>
            </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
