        animate={{ opacity: 1, scale: 1 }}
        className="relative w-full max-w-6xl h-[90vh] md:h-[75vh] flex flex-col md:flex-row shadow-[0_80px_160px_rgba(0,0,0,1)] rounded-sm overflow-hidden bg-black/20"
