                          <User size={18} className="text-[#d4af37]"/> {lang === 'zh' ? '种族' : 'Species'}
                        </span>
                        <span className={`
                          ${lang === 'zh' ? 'text-2xl md:text-3xl font-title' : 'text-xl md:text-2xl font-fantasy font-bold'}
                          pb-2 border-b-2 border-black/10 block text-[#1a120b]
                        `}>
                            {lang === 'zh' ? char.type : (char.typeEn || char.type)}
                        </span>
                    </div>
                </div>

                {/* Legendary Saga Block - Fills space */}
                {(char.deeds || char.deedsEn) && (
                  <div className="pt-10 border-t border-black/5">
                    <h4 className="font-mono text-[12px] md:text-[14px] font-black opacity-30 uppercase tracking-[0.4em] mb-6">
                      {lang === 'zh' ? '史诗事迹' : 'LEGENDARY SAGA'}
                    </h4>
                    <p className={`
                      ${lang === 'zh' ? 'text-xl md:text-2xl' : 'text-lg md:text-xl font-fantasy italic'}
                      text-[#5c4d3c] leading-relaxed
                    `}>
                      {lang === 'zh' ? char.deeds : char.deedsEn}
                    </p>
                  </div>
                )}
              </div>

              {/* Navigation Controls */}
              <div className="mt-12 md:mt-16 pt-10 flex items-center justify-between border-t border-black/10">
                  <div className="flex gap-6">
                    <button 
                        onClick={prevPage}
                        disabled={currentPage === 0}
                        className="w-16 h-16 flex items-center justify-center bg-[#1a120b] text-[#d4af37] rounded-sm disabled:opacity-20 hover:scale-110 transition-all shadow-2xl border border-[#d4af37]/20"
                    >
                        <ChevronLeft size={32} />
                    </button>
                    <button 
                        onClick={nextPage}
                        disabled={currentPage === LOTR_CHARACTERS.length - 1}
                        className="w-16 h-16 flex items-center justify-center bg-[#1a120b] text-[#d4af37] rounded-sm disabled:opacity-20 hover:scale-110 transition-all shadow-2xl border border-[#d4af37]/20"
                    >
                        <ChevronRight size={32} />
                    </button>
                  </div>
                  <div className="text-right">
                      <span className="block font-mono text-[12px] opacity-40 uppercase tracking-[0.3em] mb-2">{lang === 'zh' ? '纪元定位' : 'Chronicle Position'}</span>
                      <span className="block font-uncial text-3xl font-bold text-[#1a120b]">{currentPage + 1} / {LOTR_CHARACTERS.length}</span>
                  </div>
              </div>
            </motion.div>
          </AnimatePresence>
        </div>
      </div>
    </div>
  );
};

