                        <Sparkles size={64} className="animate-pulse" />
                        <div className="absolute inset-0 border-4 border-dashed border-[#1a120b]/20 rounded-full animate-spin-slow"></div>
                    </div>
                    <div className="space-y-6">
                        <h1 className="text-5xl md:text-8xl font-black text-[#1a120b] uppercase tracking-tighter font-uncial drop-shadow-sm">
