                            {lang === 'zh' ? '开启试炼' : 'BEGIN TRIAL'}
                        </motion.button>
                        <button onClick={onBack} className="text-[#5c4d3c] font-mono text-xs uppercase tracking-widest hover:text-[#1a120b] transition-colors flex items-center gap-2">
                           <Compass size={14} /> {lang === 'zh' ? '返回西境档案馆' : 'BACK TO ARCHIVES'}
                        </button>
