                    >
                        <div className="w-full h-full relative group">
                            <div className="absolute -inset-2 md:-inset-6 border-[8px] md:border-[16px] border-[#1a120b] shadow-[0_20px_60px_rgba(0,0,0,0.8)] z-0 rounded-sm"></div>
