                                <GenerativeImage 
                                    initialPrompt={resultChar.imagePrompt}
                                    alt={lang === 'zh' ? resultChar.name : (resultChar.nameEn || resultChar.name)}
                                    stylePreset="LOTR_VINTAGE"
